Create a simple application with a counter component:
package example

import io.github.edadma.fluxus.*

object MyApp {
  def main(args: Array[String]): Unit = {
    render(App, "app")
  }

  def App: FluxusNode = {
    val (count, setCount, _) = useState(0)

    div(
      cls := "container",
      h1("My First Fluxus App"),
      p(s"Count: $count"),
      button(
        onClick := (() => setCount(count + 1)),
        "Increment"
      )
    )
  }
}
Create an index.html file:
<!DOCTYPE html>
<html>
  <head>
    <meta charset="UTF-8">
    <title>My Fluxus App</title>
    <style>
      .container {
        max-width: 800px;
        margin: 0 auto;
        padding: 2rem;
        font-family: system-ui, sans-serif;
      }
      button {
        padding: 0.5rem 1rem;
        background: #0077cc;
        color: white;
        border: none;
        border-radius: 4px;
        cursor: pointer;
      }
    </style>
  </head>
  <body>
    <div id="app"></div>
    <script src="./target/scala-3.6.4/my-fluxus-app-fastopt.js"></script>
  </body>
</html>

import { defineConfig } from "vite";
import scalaJSPlugin from "@scala-js/vite-plugin-scalajs";

export default defineConfig({
  plugins: [scalaJSPlugin({
    cwd: ".",
    projectID: "root"
  })],
});

{
  "name": "my-fluxus-app",
  "version": "0.0.1",
  "type": "module",
  "scripts": {
    "dev": "vite",
    "build": "vite build",
    "preview": "vite preview"
  },
  "devDependencies": {
    "@scala-js/vite-plugin-scalajs": "^1.0.0",
    "vite": "^4.3.9"
  }
}
Now you can run the development server with:
npm run dev

Fluxus provides a set of helper functions to create Virtual DOM nodes:
// Creating element nodes
div(cls := "container", "Hello, world!")

// Creating nested structures
div(
  cls := "card",
  h1(cls := "title", "Card Title"),
  p(cls := "content", "Card content goes here")
)

// Conditional rendering
div(
  if (isLoggedIn) 
    button(onClick := logout, "Log out")
  else 
    button(onClick := login, "Log in")
)

Function components are defined as functions that accept a Props type parameter and return a FluxusNode:
case class UserProps(name: String, age: Int)

val UserProfile = (props: UserProps) => {
  div(
    cls := "user-profile",
    h2(s"${props.name}"),
    p(s"Age: ${props.age}")
  )
}

To use a component, you call it with the <> operator and its props:
UserProfile <> UserProps("John Doe", 30)
For components that don’t need props, you can use the NoProps type:
val Header = (_: NoProps) => {
  header(
    cls := "app-header",
    h1("My Application")
  )
}

// Usage
Header <> noProps
Alternatively, you can define a component that takes Unit:
val Footer = () => {
  footer(
    p("© 2025 My Company")
  )
}

// Usage
Footer <> ()

Components can be composed to build more complex UIs:
case class AppProps(user: User)

val App = (props: AppProps) => {
  div(
    cls := "app",
    Header <> noProps,
    UserProfile <> UserProps(props.user.name, props.user.age),
    Footer <> ()
  )
}

When rendering lists of components, it’s important to provide a key property to help Fluxus identify which items have changed, been added, or been removed:
case class TodoItemProps(
  key: String,  // Including key in the props is recommended
  text: String,
  completed: Boolean,
  onToggle: () => Unit
)

val TodoList = (props: TodoListProps) => {
  ul(
    cls := "todo-list",
    props.items.map(item => 
      TodoItem <> TodoItemProps(
        key = item.id,
        text = item.text,
        completed = item.completed,
        onToggle = () => props.onToggle(item.id)
      )
    )
  )
}

Fluxus batches multiple state updates that occur within the same event loop iteration. This means multiple calls to state setters will result in only one re-render:
val (count, setCount, _) = useState(0)

// These will be batched into a single update
button(
  onClick := (() => {
    setCount(count + 1)
    setCount(count + 2)
  })
)
However, functional updates will apply sequentially:
val (count, _, updateCount) = useState(0)

// These will apply sequentially, resulting in count = 2
button(
  onClick := (() => {
    updateCount(c => c + 1)
    updateCount(c => c + 1)
  })
)

useEffect lets you perform side effects in function components:
// Effect runs after every render
useEffect(() => {
  document.title = s"Count: $count"
})

// Effect runs only when count changes
useEffect(() => {
  document.title = s"Count: $count"
}, Seq(count))

// Effect runs only once (on mount)
useEffect(() => {
  val subscription = subscribeToData()

  // Cleanup function (runs before next effect or on unmount)
  () => subscription.unsubscribe()
}, Seq())
The useEffect hook takes a function to run after the component renders, and an optional dependency array. If any value in the dependency array changes, the effect will run again.

useMemo memoizes expensive calculations so they only recompute when dependencies change:
val memoizedValue = useMemo(
  () => {
    computeExpensiveValue(a, b)
  },
  Seq(a, b)
)

useCallback memoizes callback functions to prevent unnecessary re-renders of child components:
val memoizedCallback = useCallback(
  () => {
    doSomething(a, b)
  },
  Seq(a, b)
)

useSignal integrates with Airstream for reactive programming:
val signal = Var(0) // Airstream signal

val App = () => {
  val count = useSignal(signal)

  div(
    p(s"Count: $count"),
    button(
      onClick := (() => signal.update(_ + 1)),
      "Increment"
    )
  )
}

You can create your own hooks to reuse stateful logic between components:
def useWindowSize(): (Int, Int) = {
  val (width, setWidth, _) = useState(dom.window.innerWidth)
  val (height, setHeight, _) = useState(dom.window.innerHeight)

  useEffect(() => {
    val handleResize = () => {
      setWidth(dom.window.innerWidth)
      setHeight(dom.window.innerHeight)
    }

    dom.window.addEventListener("resize", handleResize)

    () => dom.window.removeEventListener("resize", handleResize)
  }, Seq())

  (width, height)
}

// Usage
val (width, height) = useWindowSize()
Custom hooks should: - Start with “use” to follow the naming convention - Call other hooks according to the rules of hooks - Return values that the component will use
By extracting common logic into custom hooks, you can keep your components focused on rendering and improve code reuse across your application.

Event handlers can access the event object to get more information:
input(
  onInput := ((e: dom.Event) => {
    val value = e.target.asInstanceOf[dom.html.Input].value
    setInputValue(value)
  }),
  typ := "text"
)
For keyboard events, you can check specific keys:
input(
  onKeyDown := ((e: dom.KeyboardEvent) => {
    if (e.key == "Enter") {
      submitForm()
    }
  }),
  typ := "text"
)

To prevent the default browser behavior for an event, use preventDefault():
form(
  onSubmit := ((e: dom.Event) => {
    e.preventDefault()
    // Handle form submission manually
    submitForm()
  }),
  // Form elements
)

Events in the DOM bubble up from the target element to its ancestors. You can stop this propagation using stopPropagation():
div(
  onClick := (() => console.log("Outer div clicked")),
  div(
    onClick := ((e: dom.Event) => {
      e.stopPropagation()
      console.log("Inner div clicked")
    }),
    "Click me"
  )
)

For large lists, you can use event delegation by attaching a single event handler to a parent element:
ul(
  onClick := ((e: dom.Event) => {
    val target = e.target.asInstanceOf[dom.Element]
    if (target.nodeName.toLowerCase == "li") {
      val id = target.getAttribute("data-id")
      handleItemClick(id)
    }
  }),
  items.map(item => 
    li("data-id" := item.id, item.name)
  )
)

For more type safety, you can define custom event handler types:
type InputChangeHandler = dom.Event => Unit
type SubmitHandler = dom.Event => Unit

// Usage
def FormComponent() = {
  val handleInputChange: InputChangeHandler = e => {
    val value = e.target.asInstanceOf[dom.html.Input].value
    setInputValue(value)
  }

  val handleSubmit: SubmitHandler = e => {
    e.preventDefault()
    submitForm()
  }

  form(
    onSubmit := handleSubmit,
    input(onInput := handleInputChange)
  )
}

When creating custom components, you can pass event handlers as props:
case class ButtonProps(
  onClick: () => Unit,
  label: String
)

val Button = (props: ButtonProps) => {
  button(
    cls := "custom-button",
    onClick := props.onClick,
    props.label
  )
}

// Usage
Button <> ButtonProps(() => console.log("Custom button clicked"), "Click me")

Here’s a complete example of form handling with events:
def LoginForm() = {
  val (username, setUsername, _) = useState("")
  val (password, setPassword, _) = useState("")
  val (error, setError, _) = useState("")

  def handleSubmit(e: dom.Event) = {
    e.preventDefault()

    if (username.isEmpty || password.isEmpty) {
      setError("Please fill in all fields")
    } else {
      setError("")
      // Submit the form
      loginUser(username, password)
    }
  }

  form(
    onSubmit := handleSubmit,

    if (error.nonEmpty) {
      div(cls := "error", error)
    },

    div(
      label("Username"),
      input(
        typ := "text",
        value := username,
        onInput := ((e: dom.Event) => 
          setUsername(e.target.asInstanceOf[dom.html.Input].value)
        )
      )
    ),

    div(
      label("Password"),
      input(
        typ := "password",
        value := password,
        onInput := ((e: dom.Event) => 
          setPassword(e.target.asInstanceOf[dom.html.Input].value)
        )
      )
    ),

    button(typ := "submit", "Log in")
  )
}

Here’s a simple example using the useState hook:
val Counter = () => {
  val (count, setCount, _) = useState(0)

  div(
    p(s"Count: $count"),
    button(
      onClick := (() => setCount(count + 1)),
      "Increment"
    )
  )
}

You can create your own hooks to reuse stateful logic between components. A custom hook is simply a function that calls other hooks.
def useFormField(initialValue: String): (String, dom.Event => Unit, Boolean) = {
  val (value, setValue, _) = useState(initialValue)
  val (touched, setTouched, _) = useState(false)

  val handleChange = (e: dom.Event) => {
    setValue(e.target.asInstanceOf[dom.html.Input].value)
    setTouched(true)
  }

  (value, handleChange, touched)
}
By convention, custom hook names should start with “use” to make it clear they follow the rules of hooks.

val Counter = () => {
  val (count, setCount, _) = useState(0)

  div(
    p(s"Count: $count"),
    button(
      onClick := (() => setCount(count + 1)),
      "Increment"
    )
  )
}

The update function is particularly useful when you need to update state based on the previous value:
val Counter = () => {
  val (count, _, updateCount) = useState(0)

  div(
    p(s"Count: $count"),
    div(
      button(
        onClick := (() => updateCount(_ - 1)),
        "Decrement"
      ),
      button(
        onClick := (() => updateCount(_ + 1)),
        "Increment"
      ),
      button(
        onClick := (() => {
          // Multiple updates in sequence
          updateCount(_ => 0) // Reset to 0
          updateCount(_ + 10) // Then add 10
        }),
        "Reset and Add 10"
      )
    )
  )
}

val LoginForm = () => {
  val (username, setUsername, _) = useState("")
  val (password, setPassword, _) = useState("")

  def handleSubmit(): Unit = {
    console.log(s"Logging in with: $username / $password")
  }

  form(
    div(
      label("Username:"),
      input(
        typ := "text",
        value := username,
        onInput := ((e: dom.Event) => 
          setUsername(e.target.asInstanceOf[dom.html.Input].value)
        )
      )
    ),
    div(
      label("Password:"),
      input(
        typ := "password",
        value := password,
        onInput := ((e: dom.Event) => 
          setPassword(e.target.asInstanceOf[dom.html.Input].value)
        )
      )
    ),
    button(
      typ := "button",
      onClick := (() => handleSubmit()),
      "Log In"
    )
  )
}

When using objects or collections as state, always update them immutably:
case class Todo(id: String, text: String, completed: Boolean)

val TodoApp = () => {
  val (todos, _, updateTodos) = useState(Vector[Todo]())
  val (newTodo, setNewTodo, _) = useState("")

  def addTodo(): Unit = {
    if (newTodo.nonEmpty) {
      updateTodos(prevTodos => 
        prevTodos :+ Todo(
          id = java.util.UUID.randomUUID().toString,
          text = newTodo,
          completed = false
        )
      )
      setNewTodo("")
    }
  }

  def toggleTodo(id: String): Unit = {
    updateTodos(prevTodos => 
      prevTodos.map(todo => 
        if (todo.id == id) todo.copy(completed = !todo.completed)
        else todo
      )
    )
  }

  div(
    div(
      input(
        typ := "text",
        value := newTodo,
        onInput := ((e: dom.Event) => 
          setNewTodo(e.target.asInstanceOf[dom.html.Input].value)
        ),
        placeholder := "Add a todo"
      ),
      button(onClick := (() => addTodo()), "Add")
    ),
    ul(
      todos.map(todo => 
        li(
          key := todo.id,
          input(
            typ := "checkbox",
            checked := todo.completed,
            onChange := (() => toggleTodo(todo.id))
          ),
          span(
            cls := (if (todo.completed) "completed" else ""),
            todo.text
          )
        )
      )
    )
  )
}

If creating the initial state is expensive, you can pass a function to useState:
val (state, setState, _) = useState(() => {
  // Expensive computation
  computeInitialState()
})
This function will only be called during the initial render.

You can call useState multiple times in the same component:
val Form = () => {
  val (name, setName, _) = useState("")
  val (age, setAge, _) = useState(0)
  val (email, setEmail, _) = useState("")

  // Component body
}

Fluxus automatically batches multiple state updates that occur within the same event handler:
button(
  onClick := (() => {
    setCount(count + 1) // These will be batched,
    setFlag(true)       // causing only one re-render
  })
)

Fluxus’s useState hook is fully typed, allowing the Scala compiler to ensure type safety:
// The type is inferred from the initial value
val (count, setCount, updateCount) = useState(0)
setCount("not a number") // Compilation error

// You can explicitly specify the type
val (items, setItems, updateItems) = useState[List[String]](List())

useEffect(() => {
  // Side effect code

  // Optional cleanup function
  () => {
    // Cleanup code
  }
}, dependencies)
Where: - The first argument is a function that contains the side effect code - The function can optionally return a cleanup function - The second argument is an optional array of dependencies

Some effects don’t require any cleanup:
val DocumentTitleComponent = (props: TitleProps) => {
  useEffect(() => {
    // Update the document title using the browser API
    document.title = props.title
  }, Seq(props.title))

  // ...
}
In this example, the effect runs when the component mounts and whenever props.title changes. There’s no need for cleanup because updating the document title doesn’t create any persistent resources.

Some effects create resources that need to be cleaned up:
val MouseTracker = () => {
  val (position, setPosition, _) = useState((0, 0))

  useEffect(() => {
    // Set up event listener
    val handleMouseMove = (e: dom.MouseEvent) => {
      setPosition((e.clientX, e.clientY))
    }

    document.addEventListener("mousemove", handleMouseMove)

    // Return a cleanup function
    () => {
      document.removeEventListener("mousemove", handleMouseMove)
    }
  }, Seq())

  div(s"Mouse position: ${position._1}, ${position._2}")
}
The cleanup function will run: - Before the component unmounts - Before the effect runs again (if the dependencies change)

val UserProfile = (props: UserProfileProps) => {
  val (user, setUser, _) = useState(Option.empty[User])
  val (loading, setLoading, _) = useState(true)
  val (error, setError, _) = useState(Option.empty[String])

  useEffect(() => {
    setLoading(true)
    setError(None)

    // Fetch user data
    fetchUser(props.userId)
      .map(userData => {
        setUser(Some(userData))
        setLoading(false)
      })
      .recover {
        case e: Exception =>
          setError(Some(e.getMessage))
          setLoading(false)
      }
  }, Seq(props.userId))

  div(
    if (loading) {
      div("Loading...")
    } else if (error.isDefined) {
      div(s"Error: ${error.get}")
    } else if (user.isDefined) {
      div(
        h1(user.get.name),
        p(user.get.email)
      )
    } else {
      div("No user data")
    }
  )
}

val ChatRoom = (props: ChatRoomProps) => {
  val (messages, setMessages, updateMessages) = useState(Vector.empty[Message])

  useEffect(() => {
    // Subscribe to chat room
    val subscription = chatService.subscribe(props.roomId, message => {
      updateMessages(prev => prev :+ message)
    })

    // Cleanup: unsubscribe when component unmounts or roomId changes
    () => subscription.unsubscribe()
  }, Seq(props.roomId))

  // ...
}

val AutoFocusInput = () => {
  val inputRef = useRef[dom.html.Input]()

  useEffect(() => {
    // Focus the input element after mounting
    inputRef.current.focus()
  }, Seq())

  input(
    ref := inputRef,
    typ := "text",
    placeholder := "This input will be focused"
  )
}

val Timer = () => {
  val (seconds, setSeconds, _) = useState(0)

  useEffect(() => {
    val interval = dom.window.setInterval(() => {
      setSeconds(seconds + 1)
    }, 1000)

    // Cleanup: clear the interval when unmounting
    () => dom.window.clearInterval(interval)
  }, Seq())

  div(s"Timer: $seconds seconds")
}

Sometimes you want to run an effect conditionally. While you can’t put useEffect inside a conditional, you can put the conditional logic inside the effect:
useEffect(() => {
  if (shouldRun) {
    // Only run the effect if shouldRun is true
    doSomething()
  }
}, Seq(shouldRun))

If you have multiple unrelated effects, split them into separate useEffect calls:
val UserDashboard = () => {
  // Track page views
  useEffect(() => {
    analytics.trackPageView("dashboard")
  }, Seq())

  // Fetch user data
  useEffect(() => {
    fetchUserData()
  }, Seq())

  // Set up event listeners
  useEffect(() => {
    // Event listeners setup and cleanup
  }, Seq())

  // ...
}
This makes your code more maintainable by keeping related logic together.

The most common use case for useRef is to access DOM elements:
val InputWithFocus = () => {
  val inputRef = useRef[dom.html.Input]()

  def handleButtonClick(): Unit = {
    // Access the DOM element directly
    inputRef.current.focus()
  }

  div(
    input(
      ref := inputRef,
      typ := "text"
    ),
    button(
      onClick := (() => handleButtonClick()),
      "Focus the input"
    )
  )
}

Unlike state, changing a ref’s value doesn’t cause a re-render:
val RenderCounter = () => {
  // This counts renders but doesn't appear in the output
  val renderCount = useRef(0)
  renderCount.current += 1

  val (count, setCount, _) = useState(0)

  div(
    p(s"Count: $count"),
    p(s"Render count: ${renderCount.current}"),
    button(
      onClick := (() => setCount(count + 1)),
      "Increment"
    )
  )
}

Refs can be used to remember the previous value of a prop or state:
def usePrevious[T](value: T): T = {
  val ref = useRef[T]()

  useEffect(() => {
    ref.current = value
  }, Seq(value))

  ref.current
}

val CounterWithPrevious = () => {
  val (count, setCount, _) = useState(0)
  val previousCount = usePrevious(count)

  div(
    p(s"Count: $count"),
    p(s"Previous count: ${Option(previousCount).getOrElse("none")}"),
    button(
      onClick := (() => setCount(count + 1)),
      "Increment"
    )
  )
}

When you need to update state frequently but don’t want to trigger re-renders, you can use a ref to track the current value and update the state less frequently:
val MouseTracker = () => {
  val [position, setPosition, _] = useState((0, 0))
  val positionRef = useRef((0, 0))

  useEffect(() => {
    const handleMouseMove = (e: dom.MouseEvent) => {
      // Update ref without causing re-render
      positionRef.current = (e.clientX, e.clientY)
    }

    // Update state (and re-render) every 100ms
    val interval = dom.window.setInterval(() => {
      setPosition(positionRef.current)
    }, 100)

    document.addEventListener("mousemove", handleMouseMove)

    () => {
      document.removeEventListener("mousemove", handleMouseMove)
      dom.window.clearInterval(interval)
    }
  }, Seq())

  div(s"Mouse position: ${position._1}, ${position._2}")
}

You can specify the exact type of DOM element you want to reference:
val VideoPlayer = () => {
  val videoRef = useRef[dom.html.Video]()

  def handlePlay(): Unit = {
    videoRef.current.play()
  }

  def handlePause(): Unit = {
    videoRef.current.pause()
  }

  div(
    video(
      ref := videoRef,
      width := "640",
      height := "360",
      controls := true,
      source(
        src := "video.mp4",
        typ := "video/mp4"
      )
    ),
    div(
      button(onClick := (() => handlePlay()), "Play"),
      button(onClick := (() => handlePause()), "Pause")
    )
  )
}

You can use forwardRef to pass a ref through a component to one of its children:
case class CustomInputProps(
  label: String,
  placeholder: String = ""
)

val CustomInput = forwardRef[CustomInputProps] { (props, ref) =>
  div(
    cls := "form-control",
    label(props.label),
    input(
      ref := ref.asInstanceOf[RefHook & { type RefType <: dom.html.Input }],
      typ := "text",
      placeholder := props.placeholder
    )
  )
}

// Usage in a parent component
val FormWithRef = () => {
  val inputRef = useRef[dom.html.Input]()

  div(
    CustomInput <> (CustomInputProps("Username", "Enter username"), inputRef),
    button(
      onClick := (() => inputRef.current.focus()),
      "Focus input"
    )
  )
}

Refs can be used to measure DOM elements after they render:
val MeasureExample = () => {
  val divRef = useRef[dom.html.Div]()
  val (dimensions, setDimensions, _) = useState((0, 0))

  useEffect(() => {
    if (divRef.current != null) {
      setDimensions((divRef.current.clientWidth, divRef.current.clientHeight))
    }
  }, Seq())

  div(
    ref := divRef,
    cls := "measured-div",
    "This div's dimensions will be measured"
  ),
  p(s"Width: ${dimensions._1}px, Height: ${dimensions._2}px")
}

You can combine refs with callbacks for more complex interactions:
val ScrollToTopButton = () => {
  val buttonRef = useRef[dom.html.Button]()
  val (isVisible, setIsVisible, _) = useState(false)

  useEffect(() => {
    val handleScroll = () => {
      setIsVisible(dom.window.scrollY > 100)
    }

    dom.window.addEventListener("scroll", handleScroll)

    () => dom.window.removeEventListener("scroll", handleScroll)
  }, Seq())

  if (isVisible) {
    button(
      ref := buttonRef,
      cls := "scroll-to-top",
      onClick := (() => dom.window.scrollTo(0, 0)),
      "↑"
    )
  } else {
    null
  }
}

val FibonacciCalculator = () => {
  val (number, setNumber, _) = useState(35)

  val fibResult = useMemo(
    () => {
      // Recursive Fibonacci - intentionally inefficient to demonstrate memoization
      def fib(n: Int): BigInt = {
        if (n <= 1) n
        else fib(n - 1) + fib(n - 2)
      }

      fib(number).toString
    },
    Seq(number) // Only recalculate when number changes
  )

  div(
    input(
      typ := "number",
      value := number.toString,
      onInput := ((e: dom.Event) => setNumber(e.target.asInstanceOf[dom.html.Input].value.toInt))
